    "content": msg.message,
    "isLocation": false,
    "callsign": msg.callsign || "",
    "replyMessageId": null,
    "files": []
};

msg.payload = JSON.stringify(payload);  // Manually stringify!

msg.headers = msg.headers || {};
msg.headers['Content-Type'] = 'application/json';

return msg;

var geolocation = {
    "type": "Feature",
        "geometry": {
        "type": "Point",
            "coordinates": [
                msg.latitude,
                msg.longitude,
            ]
    },
    "properties": {
        "name": "MapReference"
    }
}


msg.payload = {
    "content": JSON.stringify(geolocation),
    "isLocation": true,
    "callsign": msg.callsign || "",
    "replyMessageId": null,
    "files": []
};

return msg;

// msg.payload currently holds the binary buffer from the file in node
var fileBuffer = Array.from(msg.payload);

msg.payload = {
    "content": msg.message || "",
    "isLocation": false,
    "callsign": msg.callsign || "",
    "replyMessageId": null,
    "files": [
        {
            "filename": msg.image_file,
            "extension": "jpeg",
            "filetype": "image/jpeg",
            "blob": fileBuffer
        }
    ]
};

return msg;

var url = msg.url || flow.get("$parent.wasos_url") + "/api/chat/messages"
var group = msg.group || env.get("group") || flow.get("$parent.wasos_group")
msg.url = url + "/api/chat/messages/" + group

var apikey = msg.api_key || flow.get("$parent.wasos_apikey")
msg.headers = msg.headers || {};
msg.headers['x-api-key'] = apikey
msg.headers['Content-Type'] = 'application/json';

// CLEAN UP old HTTP properties that might interfere
delete msg.statusCode;
delete msg.responseUrl;
delete msg.redirectList;
delete msg.retry;
delete msg.responseCookies;

return msg;

global.set("wasos_url", (msg.url || env.get("url")))
msg.url = global.get("wasos_url") + "/apisec/login"

let user = msg.username || env.get("username");
let pass = msg.password || env.get("password");
let auth = Buffer.from(user + ":" + pass).toString('base64');

msg.headers = msg.headers || {};
msg.headers['Authorization'] = "Basic " + auth;

return msg;

let rawLog = msg.payload

msg.payload = rawLog.map(({ 
  id,
  text,
  timeCreated,
  loggedByFullName
  }) => ({
  id,
  text,
  timeCreated,
  loggedByFullName,
  client: "rayvn"  // Added to every entry
}));

global.set("masterLog", msg.payload);
return msg;

let rayvnConfig = global.get('rayvnConfig') || {};

if (msg.topic === 'rayvn_api_key') {
    rayvnConfig.apiKey = msg.payload;
} else if (msg.topic === 'log_name') {
    rayvnConfig.logName = msg.payload;
}

global.set('rayvnConfig', rayvnConfig);

return null;

let wasosConfig = global.get('wasosConfig') || {};

if (msg.topic === 'wasos_username') {
    wasosConfig.username = msg.payload;
} else if (msg.topic === 'wasos_password') {
    // IKKE lagre passordet - sett det bare på meldingen
    msg.password = msg.payload;
    return msg;  // Send direkte til neste node
} else if (msg.topic === 'chatroom_name') {
    wasosConfig.chatroom = msg.payload;
}

global.set('wasosConfig', wasosConfig);

return null;

let rayvnConfig = global.get('rayvnConfig') || {};

node.warn('Retrieved Rayvn config: ' + JSON.stringify({ ...rayvnConfig, apiKey: '***' }));

if (!rayvnConfig.apiKey || !rayvnConfig.logName) {
    node.warn('Missing required Rayvn fields');
    msg.payload = 'Vennligst fyll ut alle påkrevde Rayvn-felt.';
    msg.topic = 'Error';
    msg.color = '#F44336';
    return msg;
}

// Prepare to fetch logs from Rayvn
msg.headers = {
    "Authorization": "Bearer " + rayvnConfig.apiKey
};
msg.url = "https://api.rayvn.global/logs";
msg.rayvnConfig = rayvnConfig; // Pass config along

return msg;

let wasosConfig = global.get('wasosConfig') || {};
let password = global.get('temp_password');  // Hent midlertidig passord

node.warn('Retrieved config (no password): ' + JSON.stringify(wasosConfig));

if (!wasosConfig.username || !password || !wasosConfig.chatroom) {
    node.warn('Missing required WaSOS fields');
    msg.payload = 'Vennligst fyll ut alle påkrevde WaSOS-felt.';
    msg.topic = 'Error';
    msg.color = '#F44336';
    return [msg, null];
}

const wasosBaseUrl = "https://dev.wasos.no";

msg.username = wasosConfig.username;
msg.password = password;
msg.url = wasosBaseUrl;

// Slett midlertidig passord etter bruk
global.set('temp_password', null);

const chatroomUrl = `${wasosBaseUrl}/api/chat/messages/${wasosConfig.chatroom}`;
global.set('wasosChatroomUrl', chatroomUrl);
global.set('wasosChatroomName', wasosConfig.chatroom);

msg.payload = `WaSOS-konfigurasjon lagret! Chatrom: ${wasosConfig.chatroom}`;
msg.topic = 'Success';
msg.color = '#4CAF50';

return [null, msg];

global.set('temp_password', msg.payload);
msg.topic = 'wasos_password';
return msg;

let chatroom = global.get('wasosChatroomName');

if (msg.payload && msg.payload.nonce) {
    // Login vellykket
    msg.payload = `WaSOS-tilkobling vellykket! Chatrom: ${chatroom}`;
    msg.color = '#4CAF50';
} else {
    // Login feilet
    msg.payload = 'WaSOS-tilkobling feilet. Sjekk brukernavn og passord.';
    msg.color = '#F44336';
}

return msg;

const rayvnConfig = msg.rayvnConfig;
const logName = rayvnConfig.logName.trim();

try {
    const logs = JSON.parse(msg.payload);

    // Find matching logs (case-insensitive exact match)
    const matches = logs.filter(log =>
        log.name.toLowerCase() === logName.toLowerCase()
    );

    if (matches.length === 0) {
        msg.payload = `Logg '${logName}' ble ikke funnet i Rayvn.`;
        msg.topic = 'Error';
        msg.color = '#F44336';
        return msg;
    }

    if (matches.length > 1) {
        // Multiple logs with same name - need user to choose
        msg.payload = `Fant ${matches.length} logger med navn '${logName}'. Vennligst kontakt administrator.`;
        msg.topic = 'Error';
        msg.color = '#F44336';
        return msg;
    }

    // Success! Store the log ID
    const logId = matches[0].id;
    global.set('rayvnLogId', logId);

    msg.payload = `Rayvn-konfigurasjon lagret! Logg: ${logName} (ID: ${logId})`;
    msg.topic = 'Success';
    msg.color = '#4CAF50';

    return msg;

} catch (e) {
    msg.payload = 'Feil ved henting av Rayvn-logger: ' + e.message;
    msg.topic = 'Error';
    msg.color = '#F44336';
    return msg;
}

let wasosApiKey = global.get('wasos_apikey');
let rayvnConfig = global.get('rayvnConfig') || {};
let rayvnLogId = global.get('rayvnLogId');

if (!wasosApiKey || !rayvnConfig.apiKey || !rayvnLogId) {
    node.warn('Systemene er ikke fullstendig konfigurert for Rayvn → WaSOS.');
    return null;
}

return msg;

const rayvnConfig = global.get('rayvnConfig') || {};
const logId = global.get('rayvnLogId');

if (!rayvnConfig.apiKey || !logId) {
    node.error('Rayvn not configured.');
    return null;
}

msg.headers = {
    "Authorization": "Bearer " + rayvnConfig.apiKey
};

msg.url = `https://api.rayvn.global/logs/${logId}/entries`;

return msg;

const entries = msg.payload || [];

// Nothing to do
if (!Array.isArray(entries) || entries.length === 0) {
    msg.payload = [];
    return msg;
}

// Sort oldest -> newest
entries.sort((a, b) => {
    return a.timeCreated - b.timeCreated;
});

// Track last forwarded entry per log
const logId = global.get('rayvnLogId') || 'default';
const key = `lastForwardedRayvnEntry_${logId}`;

const lastId = global.get(key);

// First run: set cursor but don't forward history
if (!lastId) {
    const latest = entries[entries.length - 1];
    global.set(key, latest.id);
    msg.payload = [];
    return msg;
}

// Collect entries after lastId
const newEntries = [];
let seen = false;

for (const entry of entries) {
    if (seen) newEntries.push(entry);
    if (entry.id === lastId) seen = true;
}

// If lastId not found, forward only latest
if (!seen) {
    const latest = entries[entries.length - 1];
    global.set(key, latest.id);
    msg.payload = [latest];
    return msg;
}

// Update cursor to newest forwarded
if (newEntries.length > 0) {
    global.set(key, newEntries[newEntries.length - 1].id);
}

msg.payload = newEntries;
return msg;

const entry = msg.payload;

// Skip if entry has the WaSOS label (prevents echo loop)
const WASOS_LABEL_ID = "8d8f4cd8-c57c-4ddd-861c-f515237c75d1";
if (entry.labels && entry.labels.some(label => label.id === WASOS_LABEL_ID)) {
    return null; // Skip this entry
}

// Skip system messages (no labels or system-generated text)
if (!entry.labels || entry.labels.length === 0) {
    // Additional check: skip if text contains system patterns
    if (entry.text.includes('har endret status') ||
        entry.text.includes('Loggen') ||
        entry.text.includes('er opprettet')) {
        return null;
    }
}

// Skip if no author name
if (!entry.loggedByFullName) {
    return null;
}

return msg;

const entry = msg.payload;

const chatroomName = global.get('wasosChatroomName');
const wasosUrl = global.get('wasos_url');
const wasosApiKey = global.get('wasos_apikey');

if (!chatroomName || !wasosUrl || !wasosApiKey) {
    node.error('WaSOS not configured');
    return null;
}

// Set headers (like your working Headers node)
msg.headers = {
    'x-api-key': wasosApiKey
};

// Set URL (like your working Headers node)
msg.url = `${wasosUrl}/api/chat/messages/${chatroomName}`;

// Build payload (like your working BuildSimpleChat) - DON'T stringify!
msg.payload = {
    "content": `[Rayvn - ${entry.loggedByFullName}] ${entry.text}`,
    "isLocation": false,
    "callsign": "Rayvn Bridge",
    "replyMessageId": null,
    "files": []
};

return msg;

let wasosApiKey = global.get('wasos_apikey');
let rayvnConfig = global.get('rayvnConfig') || {};
let rayvnLogId = global.get('rayvnLogId');

if (!wasosApiKey || !rayvnConfig.apiKey || !rayvnLogId) {
    node.warn('Systemene er ikke fullstendig konfigurert. Vennligst fullfør både WaSOS- og Rayvn-konfigurasjon.');
    return null;
}

return msg;

let wasosApiKey = global.get('wasos_apikey');
let chatroomUrl = global.get('wasosChatroomUrl');

if (!wasosApiKey || !chatroomUrl) {
    node.error('WaSOS not configured. Please submit WaSOS configuration first.');
    return null;
}

msg.headers = {
    'x-api-key': wasosApiKey
};
msg.url = chatroomUrl + '?limit=50';

return msg;

const body = msg.payload || {};
const messages = Array.isArray(body.messages) ? body.messages : [];

// Nothing to do
if (messages.length === 0) {
    msg.payload = [];
    return msg;
}

// Sort oldest -> newest using numeric timestamps (avoids TS complaining)
messages.sort((a, b) => {
    const ta = new Date(a.createdAt).getTime();
    const tb = new Date(b.createdAt).getTime();
    return ta - tb;
});

// Track last forwarded per room
const roomId = String(messages[0].roomId || "default");
const key = `lastForwardedId_${roomId}`;

const lastId = global.get(key);

// First run: set cursor but don't forward history
if (!lastId) {
    const latest = messages[messages.length - 1];
    global.set(key, latest.id);
    msg.payload = [];
    return msg;
}

// Collect messages after lastId
const newMessages = [];
let seen = false;

for (const m of messages) {
    if (seen) newMessages.push(m);
    if (m.id === lastId) seen = true;
}

// If lastId not found, forward only latest (prevents spam)
if (!seen) {
    const latest = messages[messages.length - 1];
    global.set(key, latest.id);
    msg.payload = [latest];
    return msg;
}

// Update cursor to newest forwarded
if (newMessages.length > 0) {
    global.set(key, newMessages[newMessages.length - 1].id);
}

msg.payload = newMessages;
return msg;

const rayvnConfig = global.get('rayvnConfig') || {};
const logId = global.get('rayvnLogId');

// Validation
if (!rayvnConfig.apiKey || !logId) {
    node.error('Rayvn not configured. Please submit Rayvn configuration first.');
    return null;
}

const m = msg.payload; // one chat message after Split

msg.headers = {
    "Authorization": "Bearer " + rayvnConfig.apiKey,
    "Content-Type": "application/json",
    "Accept": "application/json"
};

msg.url = `https://api.rayvn.global/logs/${logId}/entry`;

// Put the chat content into Rayvn entry text
msg.payload = {
    text: `[${m.username}] ${m.content}`,
    keyEvent: false,
    releasedInfo: false,
    labels: [
        { id: "8d8f4cd8-c57c-4ddd-861c-f515237c75d1" }
    ]
};

return msg;
